pack_kernel:
// PRIVATE_CODES_NIBBLE_PREPACK_BEGIN: load-once pure-byte permutation, never timed in inference.
extern "C" __global__ void ts_bench_nvfp4_nibble_pack(const uint32_t* __restrict__ src,
    uint32_t* __restrict__ dst, long long words)
{
    const long long i=(long long)blockIdx.x*blockDim.x+threadIdx.x;
    if(i>=words)return;
    const uint32_t q=src[i];
    const uint32_t lo=(q&0xFu)|((q>>4)&0xF0u)|((q>>8)&0xF00u)|((q>>12)&0xF000u);
    const uint32_t hi=((q>>4)&0xFu)|((q>>8)&0xF0u)|((q>>12)&0xF00u)|((q>>16)&0xF000u);
    dst[i]=lo|(hi<<16);
}
// PRIVATE_CODES_NIBBLE_PREPACK_END
